"""Render report_draft.md: auto-generated evidence + prompts for the analyst's own interpretation."""
from __future__ import annotations

import json
from pathlib import Path

import pandas as pd


def _tbl(df: pd.DataFrame, floatfmt="%.3f") -> str:
    if df is None or df.empty:
        return "_(not available)_"
    return df.to_markdown(index=False, floatfmt=".3f") if _has_tabulate() else "```\n" + df.round(3).to_string(index=False) + "\n```"


def _has_tabulate() -> bool:
    try:
        import tabulate  # noqa: F401
        return True
    except ImportError:
        return False


def render_report(cfg, meta: dict, tables: dict, figs: dict, findings: list[dict], tel_laps: dict | None,
                  tel_info: dict | None) -> str:
    a, b = cfg.driver_a, cfg.driver_b
    rel = lambda p: "figures/" + Path(p).name if p else None
    img = lambda k, cap: f"![{cap}]({rel(figs[k])})" if k in figs else f"_(figure '{k}' not produced)_"
    f_md = "\n\n".join(
        f"### O{i}. {f['title']}\n**Evidence.** {f['evidence']}\n\n**Robustness.** {f['robustness']}\n\n"
        f"**Caveat.** {f['caveat']}\n\n**Needed to go further.** {f['needed']}\n\n"
        f"> **Your interpretation (replace this):** what do the plots show, what alternative explanations remain, "
        f"and what would change your mind?"
        for i, f in enumerate(findings, 1))
    wx = meta.get("weather")
    return f"""# F1 Lap & Stint Performance Analyser: {meta.get('event', cfg.gp)} {cfg.year}, {meta.get('session_name', cfg.session)}
**Drivers:** A = {a}, B = {b}  |  **Convention:** delta = time_B - time_A, positive means {a} is faster.

> DRAFT generated by `python -m f1analyser analyse`. Numbers are computed; **interpretation is yours**. Keep 3-5
> observations, delete any you cannot defend, and rewrite each in your own words.

## 1. Executive summary (write last, 4-6 lines)
- Question asked:
- Main finding, with number and uncertainty:
- Strongest alternative explanation:
- What I would do next:

## 2. Data and method
- **Source:** F1 live-timing data via FastF1 {meta.get('fastf1_version')} (see `docs/DATA_SOURCE.md`); session date {meta.get('session_date')}.
- **Weather:** {json.dumps(wx) if wx else 'not available'}
- **Lap filters** (counts per driver in `tables/exclusion_summary.csv`): out/in laps, lap 1, non-green track status
  ({'yellow allowed' if cfg.allow_yellow else 'green only'}), deleted laps, FastF1 `IsAccurate`={cfg.use_is_accurate},
  slower than {cfg.quick_lap_threshold:.2f} x driver's best valid lap. Traffic = gap to car ahead < {cfg.traffic_gap_s}s at the timing line.
- **Statistics:** percentile bootstrap ({cfg.n_bootstrap} resamples, seed {cfg.seed}); OLS slopes with t-based 95% CIs.
- **Telemetry:** laps {tel_laps and tel_laps['lap_a']} ({a}) / {tel_laps and tel_laps['lap_b']} ({b}), selection `{tel_laps and tel_laps['mode']}`: {tel_laps and tel_laps['reason']}.
  Resampled to {cfg.grid_step_m:g} m; B's distance rescaled by {tel_info and round(tel_info['b_distance_scale'], 4)} to match A's length.

{_tbl(tables.get('exclusion_summary'))}

## 3. Lap and sector analysis
{_tbl(tables.get('best_laps'))}

{_tbl(tables.get('lap_stats'))}

{_tbl(tables.get('sectors'))}

{_tbl(tables.get('theoretical_best'))}

{img('lap_distribution', 'Lap distribution')}
{img('sector_deltas', 'Sector deltas')}
{img('paired_delta', 'Paired lap delta')}

## 4. Telemetry comparison
{img('telemetry', 'Telemetry')}
{img('dominance_map', 'Dominance map')}
{img('minisector_bars', 'Mini-sector bars')}

{_tbl(tables.get('corners'))}

{_tbl(tables.get('channel_summary'))}

## 5. Stint analysis
{img('stints', 'Stints')}
{img('relative_pace', 'Relative pace')}
{img('fuel_sensitivity', 'Fuel sensitivity')}

{_tbl(tables.get('stint_table'))}

## 6. Observations
{f_md}

## 7. Caveats (keep, edit, add)
- Differences in traffic, fuel load, track evolution, tyre state and driver inputs are not controlled; filters reduce, not remove, them.
- Slopes are apparent lap-time trends, not tyre degradation rates; the fuel effect is an assumed range.
- Telemetry comparison uses two laps; brake is boolean; ~4-5 Hz sampling; distance is integrated and rescaled.
- One session, two drivers: no claim generalises to other circuits or conditions.

## 8. Next steps
- Repeat on a second race / the teammate pair across more events.
- Add: tyre temperatures/pressures, fuel mass, engine modes (team data); more lap pairs per driver.

## 9. Reproduce
```
{meta.get('command', 'python -m f1analyser analyse ...')}
```
Environment: FastF1 {meta.get('fastf1_version')}, pandas {meta.get('pandas_version')}, numpy {meta.get('numpy_version')}, scipy {meta.get('scipy_version')}, matplotlib {meta.get('matplotlib_version')}.
"""
